"""Portable interactive preview: the real engine and fixed source-art cells, no wagers."""
from pathlib import Path
import base64,json
root=Path(__file__).resolve().parent.parent;out=root.parent/'output'
def asset(name):return 'data:image/webp;base64,'+base64.b64encode((root/'assets/swamp/symbols'/name).read_bytes()).decode()
images=[asset(n) for n in ['fish_01.webp','lantern.webp','catfish.webp','bait_jar.webp','tackle_box.webp','scatter.webp']]
head='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VAULT · Symbol Drop Preview</title><style>
*{box-sizing:border-box}body{margin:0;background:#090e18;color:#f8e4b5;font:14px Arial}main{width:min(720px,100%);margin:20px auto;padding:18px}h1{font-size:23px;letter-spacing:.12em}p{color:#b7bfd0;line-height:1.5}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:15px 0}button,select{min-height:44px;border:1px solid #c3984e;border-radius:8px;background:#152234;color:#ffe8b0;padding:10px;font-weight:bold}button:disabled{opacity:.4}.grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:4px;border:3px solid #ae8343;background:#040a10;padding:8px;overflow:hidden;border-radius:15px}.cell{position:relative;aspect-ratio:1;background:#122023;display:grid;place-items:center;border:1px solid #4a5855;border-radius:7px}.cell img{width:95%;height:95%;object-fit:contain}output{display:block;margin:18px 0;font:13px monospace;line-height:1.6;white-space:pre-wrap}.hint{font-size:12px}label{display:flex;gap:6px;align-items:center}@media(max-width:440px){main{padding:12px;margin:4px auto}h1{font-size:19px}}
'''
body='''</style><main><small>VAULT · ANIMATION LAYER</small><h1>SYMBOL DROP SYSTEM</h1><p>Фиксированное поле: демонстрация анимации без ставок, RNG и выплат.</p><div class="toolbar"><select id="mode" aria-label="Drop mode"><option value="classic">CLASSIC DROP</option><option value="premium">PREMIUM SMOOTH</option><option value="impact">IMPACT DROP</option></select><select id="speed" aria-label="Speed"><option value="normal">NORMAL</option><option value="quick">QUICK ×0.65</option><option value="turbo">TURBO ×0.4</option></select><select id="columns" aria-label="Columns"><option>STAGGERED_COLUMNS</option><option>SEQUENTIAL_COLUMNS</option></select></div><div class="toolbar"><label><input type="checkbox" id="anticipation">2 SCATTERS · ANTICIPATION</label><label><input type="checkbox" id="reduced">REDUCED MOTION</label></div><div class="grid" id="grid"></div><div class="toolbar"><button id="play">PLAY DROP ↻</button></div><output id="result">READY</output><p class="hint">Classic → Derby / Swamp · Premium → Heist / MAGNET · Impact → Critter. Все режимы воспроизводят одно и то же поле. Предпросмотр использует реальные WebP-символы Swamp и тот же общий animation engine.</p></main>'''
script=r'''let currentGame='swamp';const images=IMAGES;const grid=document.getElementById('grid');for(let i=0;i<15;i++){const node=document.createElement('div');node.className='cell';node.innerHTML='<img alt="Fixed preview symbol">';grid.append(node);}function draw(){[...grid.children].forEach((n,i)=>{const scatter=document.getElementById('anticipation').checked&&[10,11].includes(i);n.dataset.symbol=scatter?'scatter':'regular';n.querySelector('img').src=images[scatter?5:i%5];});}window.previewPlay=async()=>{draw();const button=document.getElementById('play');button.disabled=true;document.getElementById('result').textContent='PLAYING · controls locked';try{const result=await VaultSymbolDrop.play('swamp',{root:grid,rows:3,cells:[...grid.children].map((node,i)=>({node,column:i%5,row:Math.floor(i/5),symbol:node.dataset.symbol})),roundId:'fixed-preview',mode:document.getElementById('mode').value,speedProfile:document.getElementById('speed').value,columnMode:document.getElementById('columns').value,reducedMotion:document.getElementById('reduced').checked,hasWin:false});document.getElementById('result').textContent='GRID SETTLED · '+Math.round(result.elapsed)+' ms\nSame cells · Same symbols · No financial operations';}finally{button.disabled=false;}};document.getElementById('play').onclick=previewPlay;draw();'''.replace('IMAGES',json.dumps(images))
(out/'VAULT_Symbol_Drop_Preview.html').write_text(head+(root/'slot-animation/presentation.css').read_text()+body+'<script>'+(root/'slot-animation/engine.js').read_text()+'</script><script>'+script+'</script></html>')
print(out/'VAULT_Symbol_Drop_Preview.html')
